#!/usr/bin/env node
/**
 * tools/check-licences.mjs — every runtime dependency declares a licence,
 * and none of them is incompatible with the MIT licence of this repository.
 *
 * Sources, in order (all offline):
 *   1. `docs/SBOM.json` — the list of the runtime components that ship
 *      inside an app bundle (generated by `tools/sbom.mjs`);
 *   2. the `package.json` of each installed dependency (`node_modules/…`) —
 *      its own `license` field, the primary declaration;
 *   3. `docs/THIRD-PARTY.md` — the documented licence table, used when the
 *      dependency is not installed in this workspace (CI installs the root
 *      only) so the answer never depends on the state of `node_modules`.
 *
 * Verdicts:
 *   - a copyleft licence (GPL family, AGPL, SSPL, EUPL, CDDL…) is
 *     **incompatible** with MIT: blocking, precise list;
 *   - a platform licence (`SEE LICENSE IN …`, `UNLICENSED` — the Forge SDK
 *     under the Atlassian Developer Terms) is declared but not permissive:
 *     reported, not blocking (the product only runs on the platform);
 *   - an undeclared licence is reported, never blocked (the brief of this
 *     tool: signal the missing ones precisely, do not fail on them).
 *
 * Usage: `node tools/check-licences.mjs [--json]` — exit 0 when nothing is
 * incompatible, 1 otherwise.
 */

import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { repoRoot } from './lib/verify.mjs';

/** SPDX identifiers accepted as MIT-compatible (permissive). */
const PERMISSIVE = new Set([
  'MIT', 'MIT-0', 'ISC', 'Apache-2.0', 'BSD-2-Clause', 'BSD-3-Clause', '0BSD',
  'Unlicense', 'CC0-1.0', 'BlueOak-1.0.0', 'Zlib', 'Python-2.0', 'WTFPL',
  'CC-BY-3.0', 'CC-BY-4.0',
]);

/** Licence families that would contaminate an MIT repository. */
const COPYLEFT = /\b(AGPL|GPL|LGPL|SSPL|EUPL|CDDL|MPL)\b|Commons Clause/i;

/** The marker of a first-party component inside the SBOM. */
function isFirstParty(component) {
  return (component.properties ?? []).some(
    (property) => property.name === 'dejavu:first-party' && property.value === 'true',
  );
}

/** Reads the documented licence table of docs/THIRD-PARTY.md. */
export function thirdPartyLicences(root) {
  const file = path.join(root, 'docs', 'THIRD-PARTY.md');
  const table = new Map();
  if (!existsSync(file)) return table;
  const text = readFileSync(file, 'utf8');
  const row = /^\|\s*`([^`]+)`\s*\|\s*([^|]*)\|\s*`([^`]+)`\s*\|/gm;
  for (const match of text.matchAll(row)) {
    table.set(match[1], match[3].trim());
  }
  return table;
}

/** The `license` field of an installed dependency, when it is installed. */
function installedLicence(root, name) {
  const candidates = [
    path.join(root, 'node_modules', name, 'package.json'),
    path.join(root, 'apps', 'brain', 'node_modules', name, 'package.json'),
    path.join(root, 'apps', 'sensor', 'node_modules', name, 'package.json'),
  ];
  for (const candidate of candidates) {
    if (!existsSync(candidate)) continue;
    try {
      const manifest = JSON.parse(readFileSync(candidate, 'utf8'));
      if (typeof manifest.license === 'string' && manifest.license.length > 0) {
        return { licence: manifest.license, source: 'node_modules' };
      }
    } catch {
      // an unreadable manifest is just one source less
    }
  }
  return undefined;
}

/** Classifies one licence declaration. */
export function classify(licence) {
  if (licence === undefined || licence.length === 0 || licence === 'NOASSERTION') {
    return { bucket: 'undeclared', blocking: false };
  }
  if (COPYLEFT.test(licence)) return { bucket: 'copyleft', blocking: true };
  if (PERMISSIVE.has(licence) || PERMISSIVE.has(licence.split(' ')[0])) {
    return { bucket: 'permissive', blocking: false };
  }
  if (/^SEE LICEN[CS]E\b/i.test(licence) || licence === 'UNLICENSED') {
    return { bucket: 'platform', blocking: false };
  }
  return { bucket: 'unknown', blocking: false };
}

/** Resolves the licence of one component: installed manifest, then the doc. */
function resolveLicence(root, name, documented) {
  const installed = installedLicence(root, name);
  if (installed) return installed;
  if (documented.has(name)) return { licence: documented.get(name), source: 'docs/THIRD-PARTY.md' };
  return { licence: undefined, source: 'none' };
}

/**
 * Checks the runtime components of the SBOM.
 * Returns `{ ok, components, incompatible, reported }`.
 */
export function checkLicences(options = {}) {
  const root = options.root ?? repoRoot;
  const sbomFile = path.join(root, 'docs', 'SBOM.json');
  if (!existsSync(sbomFile)) {
    return { ok: false, components: [], incompatible: [], reported: ['docs/SBOM.json is missing'] };
  }
  const sbom = JSON.parse(readFileSync(sbomFile, 'utf8'));
  const documented = thirdPartyLicences(root);
  const components = [];
  const incompatible = [];
  const reported = [];
  for (const component of sbom.components ?? []) {
    if (isFirstParty(component)) continue; // covered by the repository licence
    const { licence, source } = resolveLicence(root, component.name, documented);
    const verdict = classify(licence);
    const entry = { name: component.name, version: component.version, licence, source, ...verdict };
    components.push(entry);
    if (verdict.blocking) incompatible.push(`${component.name}@${component.version}: ${licence}`);
    if (verdict.bucket !== 'permissive') {
      reported.push(`${component.name}@${component.version}: ${licence ?? 'licence not declared'} (${verdict.bucket}, via ${source})`);
    }
  }
  return { ok: incompatible.length === 0, components, incompatible, reported };
}

const invokedDirectly =
  process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) {
  const result = checkLicences();
  if (process.argv.includes('--json')) {
    console.log(JSON.stringify(result, null, 2));
  } else {
    console.log(`Licences : ${result.components.length} dépendance(s) runtime du SBOM`);
    for (const item of result.reported) console.log(`  - signalé : ${item}`);
    for (const item of result.incompatible) console.error(`  - incompatible MIT : ${item}`);
    console.log(result.ok ? 'Licences : OK (rien d’incompatible avec MIT)' : `Licences : ${result.incompatible.length} licence(s) incompatible(s)`);
  }
  process.exit(result.ok ? 0 : 1);
}
